"""Meridian CRM RBAC permission check."""

from typing import Any


def _value(mapping: dict, key: str) -> str:
    """Return a legacy string field, treating a missing value as blank."""
    value = mapping.get(key, "")
    return "" if value is None else value


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether *user* has the requested legacy RBAC permission."""
    role_id = _value(user, "ROLE_ID")

    permission_row: dict[str, Any] | None = None
    for row in role_rows:
        if (
            _value(row, "role_id") == role_id
            and _value(row, "object") == object
            and _value(row, "action") == action
        ):
            permission_row = row
            break

    # A permission row is required even for ADMIN.
    if permission_row is None:
        return False

    # A row already soft-deleted cannot be deleted again.  Blank DEL_FLG is N.
    if action == "DELETE" and _value(record, "DEL_FLG") not in ("", "N"):
        return False

    # ADMIN bypasses scope only; it does not bypass the permission-row requirement.
    if role_id == "ADMIN":
        return True

    scope = _value(permission_row, "scope")
    if scope == "ALL":
        return True
    if scope == "TEAM":
        return _value(user, "TEAM_CD") == _value(record, "TEAM_CD")
    if scope == "OWN":
        return _value(record, "OWNER_UID") == _value(user, "USR_ID")
    return False
